package com.fixflow.mall.api;

import com.fixflow.mall.api.dto.CreateOrderRequest;
import com.fixflow.mall.domain.MallOrder;
import com.fixflow.mall.service.OrderService;
import com.fixflow.mall.service.UserService;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api")
public class MallController {

    private final UserService userService;
    private final OrderService orderService;

    public MallController(UserService userService, OrderService orderService) {
        this.userService = userService;
        this.orderService = orderService;
    }

    @GetMapping("/users/{userId}/nickname")
    public String nickname(@PathVariable Long userId) {
        return userService.getNickname(userId);
    }

    @PostMapping("/orders")
    public MallOrder createOrder(@RequestBody CreateOrderRequest request) {
        return orderService.createOrder(request);
    }

    @GetMapping("/orders/{orderId}")
    public MallOrder getOrder(@PathVariable("orderId") Long orderId) {
        // BUG-005: @PathVariable name mismatch, binding fails.
        return orderService.findOrder(orderId);
    }

    @GetMapping("/orders/{orderId}/first-item")
    public Long firstItem(@PathVariable Long orderId) {
        return orderService.firstItemId(orderId);
    }
}

