package com.fixflow.mall.api;

import com.fixflow.mall.domain.MallOrder;
import com.fixflow.mall.service.OrderService;
import com.fixflow.mall.service.UserService;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.mockito.Mockito.when;

@ExtendWith(MockitoExtension.class)
@DisplayName("MallController 单元测试")
class MallControllerTest {

    @Mock
    private UserService userService;

    @Mock
    private OrderService orderService;

    @InjectMocks
    private MallController mallController;

    private MallOrder testOrder;

    @BeforeEach
    void setUp() {
        testOrder = new MallOrder();
        testOrder.setId(100L);
        testOrder.setUserId(1L);
    }

    @Test
    @DisplayName("正向测试: 通过正确的路径变量名查询订单应返回订单对象")
    void getOrder_ValidOrderId_ShouldReturnOrder() {
        // Given
        Long validOrderId = 100L;
        when(orderService.findOrder(validOrderId)).thenReturn(testOrder);

        // When
        MallOrder result = mallController.getOrder(validOrderId);

        // Then
        assertEquals(testOrder, result);
        assertEquals(100L, result.getId());
    }

    @Test
    @DisplayName("边界测试: 查询不存在的订单ID应返回null (修复后不再抛出MissingPathVariableException)")
    void getOrder_NonExistingOrderId_ShouldReturnNull() {
        // Given
        Long nonExistingOrderId = 999L;
        when(orderService.findOrder(nonExistingOrderId)).thenReturn(null);

        // When
        MallOrder result = mallController.getOrder(nonExistingOrderId);

        // Then
        assertNull(result);
    }

    @Test
    @DisplayName("边界测试: 查询边界订单ID (最小值) 应正常处理")
    void getOrder_MinOrderId_ShouldWork() {
        // Given
        Long minOrderId = 1L;
        when(orderService.findOrder(minOrderId)).thenReturn(testOrder);

        // When
        MallOrder result = mallController.getOrder(minOrderId);

        // Then
        assertEquals(testOrder, result);
    }

    @Test
    @DisplayName("边界测试: 查询边界订单ID (最大值) 应正常处理")
    void getOrder_MaxOrderId_ShouldWork() {
        // Given
        Long maxOrderId = Long.MAX_VALUE;
        when(orderService.findOrder(maxOrderId)).thenReturn(testOrder);

        // When
        MallOrder result = mallController.getOrder(maxOrderId);

        // Then
        assertEquals(testOrder, result);
    }
}
